interface Row {
  id: number;
  label: string;
}

const before: Row[] = [
  { id: 1, label: 'A' },
  { id: 2, label: 'B' },
  { id: 3, label: 'C' },
];
const after: Row[] = [
  { id: 2, label: 'B' },
  { id: 3, label: 'C2' },
  { id: 4, label: 'D' },
];

interface Diff {
  created: number;
  removed: number;
  updated: number;
  kept: number;
}

function diffWithoutTrackBy(oldRows: Row[], newRows: Row[]): Diff {
  // TODO 1 : sans trackBy, tous les anciens nœuds sont détruits et tous les nouveaux sont créés
  return { created: 0, removed: 0, updated: 0, kept: 0 };
}

function diffWithTrackBy(oldRows: Row[], newRows: Row[]): Diff {
  // TODO 2 : l'identité est l'id : created = ids nouveaux, removed = ids disparus,
  //          updated = id conservé dont le label a changé, kept = id conservé et identique
  return { created: 0, removed: 0, updated: 0, kept: 0 };
}

function operations(diff: Diff): number {
  // TODO 3 : nombre d'opérations DOM : created + removed + updated
  return 0;
}

const naive = diffWithoutTrackBy(before, after);
const tracked = diffWithTrackBy(before, after);
console.log(`Sans trackBy: supprimés=${naive.removed} créés=${naive.created} mis à jour=${naive.updated} conservés=${naive.kept}`);
console.log(`Avec trackBy: supprimés=${tracked.removed} créés=${tracked.created} mis à jour=${tracked.updated} conservés=${tracked.kept}`);
console.log(`Opérations DOM évitées: ${operations(naive) - operations(tracked)}`);
